export function updateAgentSource(sourceHealth, analysis) {
  const sources = sourceHealth?.sources || [];
  const source = sources.find(item => item.id === 'agent-analysis');
  if (!source) return;
  source.status = analysis.analysisStatus === 'success' ? 'ok'
    : analysis.analysisStatus === 'partial' ? 'partial'
      : 'unavailable';
  source.successful = ['success', 'partial'].includes(analysis.analysisStatus) ? 1 : 0;
  source.lastSuccessAt = analysis.generatedAt || null;
  source.analysisStatus = analysis.analysisStatus;
  source.comparisonStatus = analysis.sourceComparison?.status || 'not_run';
  if (source.status !== 'ok') sourceHealth.status = 'limited';
}

export function mergeAgentSummaryRows(dashboard, rows, now = new Date().toISOString()) {
  rows = rows.filter(row => !String(row.run_id || '').startsWith('sprint-settings:'));
  const projectNames = (dashboard.projects || []).map(project => project.name);
  const analysis = buildAgentAnalysis(rows, projectNames, now);
  const expectedRunId = `${kstDate(now)}-morning`;
  const inputGeneratedAt = dashboard.agentHandoff?.generatedAt || dashboard.generatedAt || null;
  const analysisGeneratedAt = analysis.generatedAt || null;
  const current = analysis.runId === expectedRunId
    && ['success', 'partial'].includes(analysis.analysisStatus)
    && (!inputGeneratedAt || !analysisGeneratedAt || Date.parse(analysisGeneratedAt) >= Date.parse(inputGeneratedAt));
  if (!current) {
    const staleAnalysis = analysis.overall
      ? { ...analysis, analysisStatus: analysis.analysisStatus === 'not_run' ? 'not_run' : 'stale' }
      : analysis;
    return { dashboard: { ...dashboard, ai: staleAnalysis }, analysis: staleAnalysis, expectedRunId, current: false };
  }

  const merged = {
    ...dashboard,
    ai: analysis,
    projects: dashboard.projects.map(project => ({
      ...project,
      notionSummary: notionSummaryFromRow(latestProjectSummaryRow(rows, project.name)),
    })),
    summarySyncedAt: now,
  };
  updateAgentSource(merged.sourceHealth, analysis);
  return { dashboard: merged, analysis, expectedRunId, current: true };
}

import fs from 'node:fs';
import path from 'node:path';
import { ROOT } from './env.mjs';

const OPENAI_RESPONSES_URL = 'https://api.openai.com/v1/responses';
const DEFAULT_OPENAI_MODEL = 'gpt-5.6-sol';

function summarizeSprints(workItems) {
  const groups = new Map();
  for (const item of workItems) {
    const sprint = item.sprint || '스프린트 미지정';
    if (!groups.has(sprint)) groups.set(sprint, []);
    groups.get(sprint).push(item);
  }
  return [...groups.entries()].map(([sprint, items]) => {
    const done = items.filter(item => ['완료', '중단'].includes(item.status)).length;
    return {
      sprint,
      total: items.length,
      done,
      completionRate: items.length ? Math.round(done / items.length * 100) : 0,
      overdue: items.filter(item => item.overdueDays > 0).length,
    };
  });
}

function slimDashboard(dashboard) {
  return {
    date: dashboard.generatedAt,
    projects: dashboard.projects.map(project => {
      const projectItems = (dashboard.workItems || []).filter(item => item.project === project.name);
      return {
        name: project.name, goal: project.goal,
        workStateCounts: {
          total: project.stats?.total || 0,
          inProgress: project.stats?.inProgress || 0,
          planned: project.stats?.planned || 0,
          review: project.stats?.review || 0,
          overdue: project.stats?.overdue || 0,
        },
        sprints: summarizeSprints(projectItems),
        managementStatus: project.managementStatus,
        workItems: projectItems.slice(0, 40).map(item => ({
          title: item.title, spec: item.spec, status: item.status, assignees: item.assignees,
          sprint: item.sprint,
          start: item.start, due: item.due, completedAt: item.completedAt,
          notionUpdatedAt: item.notionUpdatedAt, latestGitAt: item.latestGitAt,
          issues: (item.issues || []).map(issue => issue.message),
        })),
        notionSummary: project.notionSummary,
        meetings: project.meetings.map(meeting => `${meeting.date?.slice(0, 10)} ${meeting.title}`),
        slackMessages: (dashboard.slack[project.name] || []).flatMap(channel =>
          channel.messages.slice(-40).map(message => `[#${channel.channel} ${message.time.slice(5, 16)} ${message.user}] ${message.text.slice(0, 250)}`)),
        gitCommits: (dashboard.git?.commits || []).filter(commit => commit.project === project.name).slice(0, 20)
          .map(commit => `${commit.committedAt} ${commit.author} ${commit.shortHash} ${commit.message}`),
      };
    }),
    deltas: dashboard.deltas || [],
    unclassifiedIssues: (dashboard.validationIssues || []).filter(issue => !issue.project),
  };
}

export function buildSummaryPrompt(dashboard) {
  const instructions = fs.readFileSync(path.join(ROOT, 'prompts', 'dashboard-summary.md'), 'utf8');
  return `${instructions}\n\n## 입력 데이터\n${JSON.stringify(slimDashboard(dashboard), null, 1)}`;
}

function outputText(response) {
  if (response?.output_text) return response.output_text;
  return (response?.output || []).flatMap(item => item.content || [])
    .filter(content => content.type === 'output_text')
    .map(content => content.text)
    .join('');
}

export async function requestOpenAISummary(prompt, options = {}) {
  const apiKey = options.apiKey ?? process.env.OPENAI_API_KEY;
  if (!apiKey) throw new Error('OPENAI_API_KEY 없음 — .env 또는 Vercel 환경변수에 설정하세요.');
  const schema = JSON.parse(fs.readFileSync(path.join(ROOT, 'schemas', 'dashboard-summary.schema.json'), 'utf8'));
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), options.timeoutMs || 300_000);
  let response;
  try {
    response = await (options.fetchImpl || fetch)(OPENAI_RESPONSES_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
      signal: controller.signal,
      body: JSON.stringify({
        model: options.model || process.env.OPENAI_MODEL || DEFAULT_OPENAI_MODEL,
        input: prompt,
        store: false,
        text: { format: { type: 'json_schema', name: 'dashboard_summary', strict: true, schema } },
      }),
    });
  } catch (error) {
    if (error.name === 'AbortError') throw new Error('OpenAI API 요약 타임아웃(300s)');
    throw error;
  } finally {
    clearTimeout(timer);
  }
  const payload = await response.json();
  if (!response.ok) throw new Error(`OpenAI API 실패(${response.status}): ${payload.error?.message || '응답 오류'}`);
  const text = outputText(payload);
  if (!text) throw new Error('OpenAI API 응답에 요약 텍스트가 없습니다.');
  return text;
}

export async function aiEnrich(dashboard, runner = requestOpenAISummary) {
  const output = await runner(buildSummaryPrompt(dashboard));
  const json = output.match(/\{[\s\S]*\}/)?.[0];
  if (!json) throw new Error('AI 응답에서 JSON 파싱 실패');
  return JSON.parse(json);
}

import { buildAgentAnalysis, latestProjectSummaryRow } from './agent-analysis.mjs';

const norm = value => String(value || '').replace(/\s+/g, '').toLowerCase();

export function notionSummaryFromRow(summary) {
  return summary ? {
    date: summary['date:기준일:start'] || summary['기준일']?.start || summary['기준일'] || summary['생성시각'],
    status: summary['프로젝트 상태'] || summary['전체 상태'],
    summary: summary['현재 진행 요약'] || summary['전체 요약'],
    blocked: summary['막힌 점'],
    decision: summary['대표 결정 필요'],
    nextAction: summary['다음 액션'],
    slackSignals: summary['Slack 신호'] || [],
  } : null;
}

export function buildBaseDashboard({ notion, slack, errors, dashboardUrl }) {
  const projects = notion.projects.map(config => {
    const summary = latestProjectSummaryRow(notion.summaryRows, config.name);
    const projectKey = norm(config.name);
    return {
      name: config.name,
      config,
      goal: config.goal || '',
      milestones: {
        scopeFreezePlannedAt: config.scopeFreezePlannedAt || null,
        productionCompletePlannedAt: config.productionCompletePlannedAt || null,
        targetAt: config.targetAt || null,
      },
      notionSummary: notionSummaryFromRow(summary),
      slack: (slack[config.name] || []).map(channel => ({ channel: channel.channel, count: channel.messages.length })),
      persistentContexts: (slack[config.name] || []).flatMap(channel => channel.persistentContexts || []),
      // Shared meeting databases do not expose their linked-view filter through
      // the API. Empty project names are therefore semantic candidates; a row
      // explicitly assigned to another project must never cross that boundary.
      meetings: notion.meetings.filter(meeting => {
        const meetingProject = norm(meeting.project);
        return !meetingProject || meetingProject === projectKey;
      }).slice(0, 40),
    };
  });
  return {
    generatedAt: new Date().toISOString(), sample: false, errors, projects,
    meetings: notion.meetings.slice(0, 40), slack,
    ai: buildAgentAnalysis(notion.summaryRows, notion.projects.map(project => project.name)),
    dashboardUrl,
  };
}

const SEOUL_TIME_ZONE = 'Asia/Seoul';
const DAY_MS = 86_400_000;

export function kstDate(value = new Date()) {
  if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: SEOUL_TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}`;
}

function dayNumber(value) {
  const date = kstDate(value);
  return date ? Math.floor(Date.parse(`${date}T00:00:00Z`) / DAY_MS) : null;
}

export function calendarDaysBetween(start, end) {
  const from = dayNumber(start);
  const to = dayNumber(end);
  if (from === null || to === null || to <= from) return 0;
  return to - from;
}

export function businessDaysBetween(start, end) {
  const from = dayNumber(start);
  const to = dayNumber(end);
  if (from === null || to === null || to <= from) return 0;
  let count = 0;
  for (let day = from + 1; day <= to; day += 1) {
    const weekday = new Date(day * DAY_MS).getUTCDay();
    if (weekday !== 0 && weekday !== 6) count += 1;
  }
  return count;
}

export function isKoreanBusinessDay(value = new Date()) {
  const day = dayNumber(value);
  if (day === null) return false;
  const weekday = new Date(day * DAY_MS).getUTCDay();
  return weekday !== 0 && weekday !== 6;
}

import { buildProjectSpecs } from './task-hierarchy.mjs';
import { buildSpecInsights } from './spec-insights.mjs';
import { buildProjectOperations } from './project-operations.mjs';

const DONE = new Set(['완료', '일시 정지', '정지', '중단']);
const IN_PROGRESS = new Set(['진행 중']);
const PLANNED = new Set(['진행 예정', '시작 전']);
const REVIEW = new Set(['확인 요청', '검토중']);

function latest(values) {
  return values.filter(Boolean).sort().at(-1) || null;
}

function earliest(values) {
  return values.filter(Boolean).sort()[0] || null;
}

function statusFor(issues) {
  if (issues.some(issue => issue.severity === 'error')) return 'error';
  if (issues.some(issue => issue.severity === 'warning')) return 'warning';
  if (issues.some(issue => issue.severity === 'check')) return 'check';
  return 'normal';
}

function isClosed(item) {
  return DONE.has(item?.status);
}

function actionableIssues(issues, tasks, workItems) {
  const workById = new Map(workItems.map(item => [item.id, item]));
  const taskById = new Map(tasks.map(task => [task.id, task]));
  return issues.filter(issue => {
    if (issue.type === 'STALE_UPDATE') return false;
    if (issue.workItemId && isClosed(workById.get(issue.workItemId) || taskById.get(issue.workItemId))) return false;
    if (!issue.workItemId && issue.specId && isClosed(taskById.get(issue.specId))) return false;
    return true;
  });
}

function buildPeople(workItems) {
  const people = new Map();
  for (const item of workItems) {
    for (const name of item.assignees || []) {
      const person = people.get(name) || { name, teams: new Set(), projects: new Set(), tasks: [] };
      person.teams.add(item.team || '기타');
      if (!isClosed(item)) {
        person.projects.add(item.project);
        person.tasks.push(item);
      }
      people.set(name, person);
    }
  }
  return [...people.values()].map(person => ({
    name: person.name,
    teams: [...person.teams],
    projects: [...person.projects],
    projectCount: person.projects.size,
    count: person.tasks.length,
    inProgressCount: person.tasks.filter(item => IN_PROGRESS.has(item.status)).length,
    overdueCount: person.tasks.filter(item => item.overdueDays > 0).length,
    missingCompletedCount: person.tasks.filter(item => item.issues?.some(issue => issue.type === 'MISSING_COMPLETED_DATE')).length,
    nearestDue: earliest(person.tasks.map(item => item.due)),
    latestGitAt: latest(person.tasks.map(item => item.latestGitAt)),
    tasks: person.tasks,
  })).sort((a, b) => b.overdueCount - a.overdueCount || b.inProgressCount - a.inProgressCount || b.count - a.count || a.name.localeCompare(b.name, 'ko'));
}

function buildProjects(baseProjects, tasks, workItems, issues, commits, slackByProject = {}) {
  return baseProjects.map(project => {
    const items = workItems.filter(item => item.project === project.name);
    const projectTasks = tasks.filter(task => task.project === project.name);
    const projectIssues = issues.filter(issue => issue.project === project.name);
    const projectCommits = commits.filter(commit => commit.project === project.name);
    const stats = {
      total: items.length,
      done: items.filter(item => item.status === '완료').length,
      inProgress: items.filter(item => IN_PROGRESS.has(item.status)).length,
      planned: items.filter(item => PLANNED.has(item.status)).length,
      review: items.filter(item => REVIEW.has(item.status)).length,
      overdue: items.filter(item => item.overdueDays > 0).length,
      missingData: items.filter(item => item.issues?.some(issue => ['MISSING_START_DATE', 'MISSING_DUE_DATE', 'MISSING_ASSIGNEE', 'MISSING_PROJECT', 'MISSING_SPEC'].includes(issue.type))).length,
      missingCompleted: items.filter(item => item.issues?.some(issue => issue.type === 'MISSING_COMPLETED_DATE')).length,
      issueCount: projectIssues.filter(issue => issue.severity !== 'info').length,
    };
    const projectOperations = buildProjectOperations(slackByProject[project.name] || []);
    const enriched = {
      ...project,
      specs: buildProjectSpecs(projectTasks, [...DONE]),
      projectOperations,
      stats: { ...stats, completionRate: stats.total ? Math.round(stats.done / stats.total * 100) : 0 },
      managementStatus: statusFor(projectIssues),
      issues: projectIssues,
      recentGitAt: latest([...items.map(item => item.latestGitAt), ...projectCommits.map(commit => commit.committedAt)])?.slice(0, 10) || null,
      nearestDue: earliest(items.filter(item => !DONE.has(item.status)).map(item => item.due)),
      teams: [...new Set(items.map(item => item.team).filter(Boolean))],
    };
    return {
      ...enriched,
      specInsights: buildSpecInsights({
        project: enriched,
        slackChannels: slackByProject[project.name] || [],
        persistentContexts: project.persistentContexts || [],
        meetings: project.meetings || [],
        commits: projectCommits,
      }),
    };
  });
}

export function buildManagementDashboard({
  base,
  tasks,
  workItems,
  ruleItems = workItems,
  issues,
  progressSetupItems = [],
  ruleStats = {},
  git,
  notionSetup,
}) {
  const visibleIssues = actionableIssues(issues, tasks, workItems);
  const projects = buildProjects(base.projects, tasks, workItems, visibleIssues, git.commits, base.slack);
  const selectedProjects = new Set(projects.map(project => project.name));
  const projectNamesWithGit = new Set(git.commits.filter(commit => selectedProjects.has(commit.project)).map(commit => commit.project));
  const mismatchProjects = new Set(visibleIssues.filter(issue => issue.type === 'GIT_NOTION_ACTIVITY_MISMATCH').map(issue => issue.project));
  const activeWorkItems = workItems.filter(item => !DONE.has(item.status));
  const activeRuleItems = ruleItems.filter(item => !DONE.has(item.status));
  const problemIds = new Set(visibleIssues.filter(issue => issue.workItemId && issue.severity !== 'info').map(issue => issue.workItemId));
  const guideViolationItems = activeRuleItems.filter(item => (item.issues || []).some(issue => issue.category === 'guide'));
  const missingDate = activeWorkItems.filter(item => item.issues?.some(issue => ['MISSING_START_DATE', 'MISSING_DUE_DATE'].includes(issue.type)));
  const workload = buildPeople(workItems);
  const unassignedTasks = workItems.filter(item => !DONE.has(item.status) && !(item.assignees || []).length);
  return {
    ...base,
    projects,
    ruleItems,
    workItems,
    guideViolationItems,
    progressSetupItems,
    workload,
    teamQueue: { unassignedTasks, count: unassignedTasks.length },
    hierarchyStats: { personalTaskLinks: workload.reduce((sum, person) => sum + person.count, 0) },
    validationIssues: visibleIssues,
    notionSetup,
    git,
    metrics: {
      activeProjects: projects.filter(project => project.stats.inProgress + project.stats.planned + project.stats.review > 0).length,
      inProgressWorkItems: workItems.filter(item => IN_PROGRESS.has(item.status)).length,
      overdueWorkItems: workItems.filter(item => item.overdueDays > 0).length,
      missingDateWorkItems: missingDate.length,
      guideViolationWorkItems: guideViolationItems.length,
      progressSetupRequiredItems: progressSetupItems.length,
      pastSprintNotStartedItems: ruleStats.pastSprintNotStartedItems || 0,
      futureSprintExcludedItems: ruleStats.futureSprintExcludedItems || 0,
      ruleNotEvaluatedItems: ruleStats.ruleNotEvaluatedItems || 0,
      excludedStatusWorkItems: ruleStats.excludedStatusWorkItems || 0,
      needsCheckProjects: projects.filter(project => project.managementStatus !== 'normal').length,
      recentGitProjects: projectNamesWithGit.size,
      gitNotionMismatchProjects: mismatchProjects.size,
      normalWorkItems: activeWorkItems.filter(item => !problemIds.has(item.id)).length,
      totalWorkItems: activeRuleItems.length,
    },
  };
}
